// Normalise R/G/B to the strongest channel and compute the IR fraction.
const p = msg.payload;
const top = Math.max(p.red, p.green, p.blue, 1);
const h = (v) => Math.floor(v * 255 / top).toString(16).padStart(2, '0');
p.colour = '#' + h(p.red) + h(p.green) + h(p.blue);
p.irFraction = p.ir / Math.max(1, p.ir + p.green);
return msg;
